import sys


def main():
    s = sys.stdin.readline().strip()
    pair = {')': '(', ']': '[', '}': '{', '>': '<'}
    st = []
    for i, c in enumerate(s):
        if c in pair:
            if st.pop() != pair[c]:
                print(i)
                return
        else:
            st.append(c)
    print(-1 if not st else len(s))


main()
